//! Imports every sample in `tests/corpus` through the reader its manifest names.
//!
//! The corpus is generated by `crates/officecore/examples/make-corpus.rs`. This
//! test keeps the committed files honest: every manifest entry must resolve to a
//! file that the named reader parses, no corpus file may be left out, and the
//! corpus must keep covering the promised formats and kinds.

use std::collections::BTreeSet;
use std::path::PathBuf;

fn corpus_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("..").join("tests").join("corpus")
}

fn manifest() -> Vec<serde_json::Value> {
    let path = corpus_root().join("manifest.json");
    let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()));
    let value: serde_json::Value =
        serde_json::from_slice(&bytes).unwrap_or_else(|error| panic!("{}: geçersiz JSON: {error}", path.display()));
    value.as_array().expect("manifest bir dizi olmalı").clone()
}

#[test]
fn every_corpus_sample_imports_through_its_reader() {
    let root = corpus_root();
    let entries = manifest();
    assert!(entries.len() >= 15, "korpus en az 15 örnek içermeli, {} bulundu", entries.len());
    let mut formats = BTreeSet::new();
    let mut kinds = BTreeSet::new();
    for entry in &entries {
        let file = entry["file"].as_str().expect("file alanı");
        let reader = entry["reader"].as_str().expect("reader alanı");
        formats.insert(entry["format"].as_str().expect("format alanı").to_string());
        kinds.insert(entry["kind"].as_str().expect("kind alanı").to_string());
        let bytes = std::fs::read(root.join(file)).unwrap_or_else(|error| panic!("{file}: {error}"));
        match reader {
            "docx::read_docx" => {
                let read = officecore::docx::read_docx(&bytes).unwrap_or_else(|error| panic!("{file}: {error}"));
                assert!(!read.document.blocks.is_empty(), "{file}: boş belge okundu");
            }
            "odf::read_odt" => {
                let read = officecore::odf::read_odt(&bytes).unwrap_or_else(|error| panic!("{file}: {error}"));
                assert!(!read.document.blocks.is_empty(), "{file}: boş belge okundu");
            }
            "xlsx::read_workbook_bytes" => {
                let read =
                    officecore::xlsx::read_workbook_bytes(&bytes).unwrap_or_else(|error| panic!("{file}: {error}"));
                assert!(!read.workbook.sheets.is_empty(), "{file}: boş çizelge okundu");
            }
            "pptx::read_pptx" => {
                let read = officecore::pptx::read_pptx(&bytes).unwrap_or_else(|error| panic!("{file}: {error}"));
                assert!(!read.deck.slides.is_empty(), "{file}: boş sunum okundu");
            }
            "udf::read_udf" => {
                let read = officecore::udf::read_udf(&bytes).unwrap_or_else(|error| panic!("{file}: {error}"));
                assert!(!read.document.blocks.is_empty(), "{file}: boş belge okundu");
            }
            other => panic!("manifest bilinmeyen okuyucu içeriyor: {other}"),
        }
    }
    for format in ["docx", "odt", "xlsx", "pptx", "udf"] {
        assert!(formats.contains(format), "korpus {format} biçimini içermeli");
    }
    for kind in ["writer", "calc", "impress"] {
        assert!(kinds.contains(kind), "korpus {kind} türünü içermeli");
    }
}

#[test]
fn the_manifest_covers_every_corpus_file() {
    let root = corpus_root();
    let listed: BTreeSet<String> = manifest().iter().map(|entry| entry["file"].as_str().unwrap().to_string()).collect();
    let mut on_disk = BTreeSet::new();
    for entry in std::fs::read_dir(&root).unwrap_or_else(|error| panic!("{}: {error}", root.display())) {
        let path = entry.expect("dizin girdisi").path();
        if path.is_file() {
            let name = path.file_name().unwrap().to_string_lossy().to_string();
            if name != "manifest.json" {
                on_disk.insert(name);
            }
        }
    }
    assert_eq!(listed, on_disk, "manifest ile diskteki dosyalar birebir örtüşmeli");
}
